export function countSudokuSolutions(values,n,boxRows,boxCols,limit=2){
 const grid=values.slice(),full=(1<<n)-1,rows=Array(n).fill(0),cols=Array(n).fill(0),boxes=Array(n).fill(0);
 const box=(i)=>Math.floor(Math.floor(i/n)/boxRows)*(n/boxCols)+Math.floor((i%n)/boxCols);
 if(grid.length!==n*n)return 0;
 for(let i=0;i<grid.length;i++){const v=grid[i];if(!Number.isInteger(v)||v<0||v>n)return 0;if(v){let bit=1<<(v-1),r=Math.floor(i/n),c=i%n,b=box(i);if((rows[r]|cols[c]|boxes[b])&bit)return 0;rows[r]|=bit;cols[c]|=bit;boxes[b]|=bit;}}
 let count=0;
 const dfs=()=>{if(count>=limit)return;let pos=-1,mask=0,min=n+1;for(let i=0;i<grid.length;i++)if(!grid[i]){let m=full&~(rows[Math.floor(i/n)]|cols[i%n]|boxes[box(i)]),k=0;for(let t=m;t;t&=t-1)k++;if(!k)return;if(k<min){pos=i;mask=m;min=k;if(k===1)break;}}if(pos<0){count++;return;}let r=Math.floor(pos/n),c=pos%n,b=box(pos);for(let m=mask;m&&count<limit;m&=m-1){let bit=m&-m;grid[pos]=Math.log2(bit)+1;rows[r]|=bit;cols[c]|=bit;boxes[b]|=bit;dfs();rows[r]^=bit;cols[c]^=bit;boxes[b]^=bit;grid[pos]=0;}};
 dfs();return count;
}
