export function verifyWordTemplate(t,n){if(t.grid.length!==n*n||t.words.length!==t.paths.length||new Set(t.words).size!==t.words.length)return false;return t.paths.every((path,i)=>{const w=t.words[i];if(path.length!==w.length||path.some(x=>!Number.isInteger(x)||x<0||x>=n*n)||path.map(x=>t.grid[x]).join("")!==w)return false;const dr=Math.floor(path[1]/n)-Math.floor(path[0]/n),dc=path[1]%n-path[0]%n;return Math.max(Math.abs(dr),Math.abs(dc))===1&&path.every((x,k)=>Math.floor(x/n)===Math.floor(path[0]/n)+k*dr&&x%n===path[0]%n+k*dc)})}
export function buildFieldChallenge(id,raw){
 if(WORD_SEARCH_BANK[id]){const tiers=WORD_SEARCH_BANK[id];for(const tier of tiers)for(const t of tier.templates)if(!verifyWordTemplate(t,tier.size))throw Error('Invalid word search');return {type:'wordsearch',prompt:'Find the listed words by tapping their first and last letters.',items:['A','B'],tiers};}
 if(id==='quin-code-breaker')return {type:'codebreaker',prompt:'Crack the hidden code. Exact = right digit and place; misplaced = right digit, wrong place.',items:[1,2,3,4,0],secret:[1,3,2],attemptLimit:8};
 if(id==='elesur-domino-village')return {type:'domino',prompt:'Join matching ends. Use every tile to reach the target.',items:[[1,2],[2,3],[3,4],'Undo'],start:1,target:4};
 if(id==='van-sudoku-master'){for(const b of SUDOKU_BANK)for(const t of b.templates)if(countSudokuSolutions(t.clues,b.size,b.boxRows,b.boxCols)!==1||countSudokuSolutions(t.solution,b.size,b.boxRows,b.boxCols)!==1||t.clues.some((v,i)=>v!==0&&v!==t.solution[i]))throw Error('Invalid Sudoku bank');return {type:'sudoku',prompt:'Complete each row, column and outlined region without repeating a number.',items:[1,2,3,4,0],tiers:SUDOKU_BANK};}
 if(ADVANCED_FIELD_CHALLENGES[id]){const data=ADVANCED_FIELD_CHALLENGES[id];for(let i=0;i<3;i++)checkAdvancedField(data,i);return JSON.parse(JSON.stringify(data));}
 if(!raw)throw Error("Missing field challenge "+id);
 const [type,prompt,items,answer,limit]=raw;let d={type,prompt};
 if(type==="budget"){d={...d,items,goal:answer,limit};const combinations=[];for(let mask=1;mask<1<<items.length;mask++){let s=0,n=0;for(let i=0;i<items.length;i++)if(mask>>i&1){s+=items[i];n++;}if(s===answer&&n===limit)combinations.push(mask)}if(!combinations.length)throw Error("Unsolvable "+id);}
 else if(type==="route"){d={...d,items:Array.from({length:9},(_,i)=>i===0?"Start":i===8?"Goal":answer.includes(i)?"Blocked":"Path"),path:items};if(items[0]!==0||items.at(-1)!==8||items.some((x,i)=>i>0&&Math.abs(x%3-items[i-1]%3)+Math.abs(Math.floor(x/3)-Math.floor(items[i-1]/3))!==1))throw Error("Broken path "+id);}
 else if(type==="pair"){d={...d,items};if(items.some(x=>items.filter(y=>y===x).length!==2))throw Error("Bad pairs "+id);}
 else {d={...d,items,answer};if(type==="select"?!Number.isInteger(answer)||answer<0||answer>=items.length:!Array.isArray(answer)||answer.some(x=>x<0||x>=items.length))throw Error("Bad answer "+id);}
 return d;
}
